const actDate = $('Parse JSON Response').first().json.date;
const actEmp  = $('Parse JSON Response').first().json.employee;

const summaryRows = $input.all().map(r => r.json);

function normDate(d) {
  if (!d) return '';
  return String(d).split('T')[0].toLowerCase().trim();
}

const normAct = normDate(actDate);

let blankRowIndex = -1;
let alreadyExists = false;

// C6:D56 range — ALL rows are data rows, no header, start from index 0
for (let i = 0; i < summaryRows.length; i++) {
  const rowDate = normDate(summaryRows[i].Date || '');
  const rowEmp  = String(summaryRows[i].Employee || '').toLowerCase().trim();
  const actEmpNorm = actEmp.toLowerCase().trim();

  if (rowDate && rowEmp) {
    if (
      (rowDate === normAct || rowDate.includes(normAct) || normAct.includes(rowDate)) &&
      rowEmp === actEmpNorm
    ) {
      alreadyExists = true;
      break;
    }
  } else if (!rowDate && !rowEmp && blankRowIndex === -1) {
    blankRowIndex = i;
  }
}

if (alreadyExists) {
  return [{ json: { skip: true, reason: 'Combo already exists in Monthly Summary' } }];
}

if (blankRowIndex === -1) {
  return [{ json: { skip: true, reason: 'No blank rows left in Monthly Summary' } }];
}

// blankRowIndex 0 = row 6 in Excel, so Excel row = blankRowIndex + 6
const excelRow = blankRowIndex + 6;

return [{
  json: {
    skip: false,
    excelRow,
    date: actDate,
    employee: actEmp,
    dateCell: 'C' + excelRow,
    employeeCell: 'D' + excelRow
  }
}];

// OpenAI ရဲ့ content list ထဲက text ကို အဆင့်ဆင့် ရှာယူပါတယ်
const content = $input.first().json.output[0].content;
const textItem = content.find(item => item.type === 'output_text');
const text = textItem ? textItem.text : "";

if (!text) {
  throw new Error("AI ဆီက စာသားရှာမတွေ့ပါဘူး။ OpenAI node settings ကို ပြန်စစ်ပေးပါ။");
}

// Markdown formatting တွေကို ရှင်းထုတ်ပါတယ်
const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();

// JSON Array အဖြစ် ပြောင်းလဲပါတယ်
const activities = JSON.parse(cleaned);

// Row တစ်ခုချင်းစီ ခွဲထုတ်ပေးပါတယ်
return activities.map(a => ({ json: a }));

